class Solution {
  public long maxScore(int[] a, int[] b) {
    long NEG = Long.MIN_VALUE / 2;
    long[] dp = {0, NEG, NEG, NEG, NEG};
    for (int x : b) {
      for (int j = 3; j >= 0; j--) {
        long v = dp[j] + (long) a[j] * x;
        if (v > dp[j + 1]) dp[j + 1] = v;
      }
    }
    return dp[4];
  }
}
